// TEMPORARY (T-013, deps-upgrade): records what every schema in schemas.ts
// answers to a fixed corpus of inputs, so zod 3 → 4 can be compared byte for
// byte. Deleted once the comparison is recorded in whats-done.md.
import { writeFileSync } from 'node:fs';
import { test } from 'vitest';
import * as S from './schemas';

const uuid = '3f2504e0-4f89-41d3-9a0c-0305e82c3301';
const long = 'x'.repeat(600);
const atoms: unknown[] = [
  undefined, null, '', '   ', 'abc', ' padded ', 'a@b.co', 'not an email', 'https://x.example/a.png', 'http://x.example',
  '#fff', '#12345g', '12:30', '24:00', '2026-10-01', uuid, 'not-a-uuid', 'verify', 'confirm', 'cancel', 'fixed', 'percent',
  'owner', 'staff', 'request', 'none', 'on_proof', 'gcash', 'holiday', 'closed', 'approve', 'reschedule', 'abc-def', 'A',
  0, 1, -1, 1.5, 3, 18, 200, 9999, true, false, [], [1], ['a'], [1, 2], {}, long, 'v1.0',
];
const nested: unknown[] = [
  [{ unitId: 1, guests: 2 }], [{ unitId: 1, guests: 2, free: 1 }], [{}], [{ unitId: 'x' }],
  [{ slotId: 1, weekdayPrice: 100, weekendPrice: 200 }], [{ slotId: 1 }],
  [{ role: 'staff', permission: 'documents:write', allowed: true }], [{ role: 'x', permission: 'y', allowed: 'z' }],
  { p256dh: 'A'.repeat(87), auth: 'B'.repeat(22) }, { p256dh: 'short', auth: 'x' },
  ['request', 'request', 'proof'], ['bogus'],
  { primary: '#fff' }, { accent: '#123456', bogus: 1 }, { english: 'Sorry' }, { english: '' },
  { methods: [], fee: { kind: 'full' }, payWithinHours: null, reviewWithinHours: null, terms: null },
  { methods: [{ kind: 'gcash', label: 'G' }], fee: { kind: 'fixed', value: 'x' }, payWithinHours: 1, reviewWithinHours: 2, terms: 't', hold: 'bad' },
  { kind: 'full' }, ['Q1', 'Q2'], [''], { a: 1 },
];
const pool = [...atoms, ...nested];

// Deterministic PRNG so the corpus is the same on both versions.
let seed = 20261028;
const rand = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pick = <T,>(a: T[]) => a[Math.floor(rand() * a.length)];

function shapeKeys(schema: any): string[] {
  let s = schema;
  for (let i = 0; i < 6 && s; i++) {
    const def = s._def ?? s.def;
    if (s.shape && typeof s.shape === 'object') return Object.keys(s.shape);
    if (typeof s.shape === 'function') return Object.keys(s.shape());
    s = def?.schema ?? def?.innerType ?? def?.in ?? def?.options?.[0];
  }
  return [];
}

function run(schema: any, input: unknown) {
  const r = schema.safeParse(input);
  if (r.success) return { ok: true, data: JSON.stringify(r.data) ?? 'undefined' };
  return { ok: false, first: S.firstError(r.error), issues: r.error.issues.map((i: any) => `${i.path.join('.')}: ${i.message}`) };
}

test('record the corpus', () => {
  const out: Record<string, unknown[]> = {};
  const schemas: [string, any][] = Object.entries(S).filter(([, v]: any) => v && typeof v.safeParse === 'function') as any;
  schemas.push(['unansweredIdsSchema(5)', S.unansweredIdsSchema(5)]);
  for (const [name, schema] of schemas) {
    const keys = shapeKeys(schema);
    const inputs: unknown[] = [...pool];
    for (const k of keys) for (const v of pool) inputs.push({ [k]: v });
    for (let n = 0; n < 400; n++) {
      const o: Record<string, unknown> = {};
      for (const k of keys) if (rand() < 0.8) o[k] = pick(pool);
      if (rand() < 0.1) o.extra = 'x';
      inputs.push(o);
    }
    out[name] = inputs.map((input) => ({ input: JSON.stringify(input) ?? 'undefined', ...run(schema, input) }));
  }
  writeFileSync(process.env.CORPUS_OUT ?? 'corpus.json', JSON.stringify(out, null, 1));
  const total = Object.values(out).reduce((n, a) => n + a.length, 0);
  console.log(`corpus: ${schemas.length} schemas, ${total} inputs`);
});

