];
const nested: unknown[] = [
  [{ unitId: 1, guests: 2 }], [{ unitId: 1, guests: 2, free: 1 }], [{}], [{ unitId: 'x' }],
  [{ slotId: 1, weekdayPrice: 100, weekendPrice: 200 }], [{ slotId: 1 }],
  [{ role: 'staff', permission: 'documents:write', allowed: true }], [{ role: 'x', permission: 'y', allowed: 'z' }],
