cd /c/Users/jsi6724/Desktop/Projects/rag-chatbot-poc && cat > /tmp/deps/diff.mjs <<'EOF'
import { readFileSync } from 'node:fs';
const [a, b] = process.argv.slice(2).map((p) => JSON.parse(readFileSync(p, 'utf8')));
let total = 0, same = 0; const kinds = new Map(); const ex = new Map();
for (const name of Object.keys(a)) {
  if (!b[name]) { console.log('missing schema', name); continue; }
  a[name].forEach((r, i) => {
    total++;
    const s = b[name][i];
    if (JSON.stringify(r) === JSON.stringify(s)) return same++;
    let k;
    if (r.ok !== s.ok) k = `ok ${r.ok}->${s.ok}`;
    else if (r.ok) k = 'data differs';
    else if (r.first !== s.first) k = `first: ${r.first.replace(/'[^']*'/g, "'…'")}  =>  ${s.first.replace(/"[^"]*"/g, '"…"')}`;
    else k = 'later issues differ';
    kinds.set(k, (kinds.get(k) ?? 0) + 1);
    if (!ex.has(k)) ex.set(k, { name, input: r.input.slice(0, 160), v3: r.first ?? r.data?.slice(0, 160), v4: s.first ?? s.data?.slice(0, 160), v3i: r.issues?.slice(0,4), v4i: s.issues?.slice(0,4) });
  });
}
console.log(`identical ${same} of ${total}`);
for (const [k, n] of [...kinds].sort((x, y) => y[1] - x[1])) console.log(String(n).padStart(6), k, '\n        e.g.', JSON.stringify(ex.get(k)).slice(0, 600));
EOF
node /tmp/deps/diff.mjs "$(cygpath -w /tmp/deps/corpus-v3.json)" "$(cygpath -w /tmp/deps/corpus-v4a.json)" 2>&1 | head -120

